149    void getPurpose(int id) {
150
151        Issue i1 = new Issue();
152        String purpose;
153        
154        System.out.println("Enter your purpose: return or issue");
155        purpose = input.next();
156
157        if (purpose.equals("issue")) {
158
159            i1.issueBook(id);
160
161        } else if (purpose.equals("return")) {
162
163            i1.returnBook(id);
164        }
165    }
166}
